namespace UniversalPOS.Domain.Entities;
public enum PurchaseStatus { Draft=0, Received=1, Cancelled=2 }
public class Purchase { private readonly List<PurchaseItem> _items=new(); public int Id {get; private set;} public int SupplierId {get; private set;} public DateTime PurchaseDateUtc {get; private set;}=DateTime.UtcNow; public string? SupplierInvoiceNumber {get; private set;} public PurchaseStatus Status {get; private set;}=PurchaseStatus.Draft; public IReadOnlyCollection<PurchaseItem> Items=>_items.AsReadOnly(); public decimal TotalAmount=>_items.Sum(x=>x.LineTotal); private Purchase(){} public Purchase(int supplierId,string? invoiceNumber=null){if(supplierId<=0)throw new ArgumentOutOfRangeException(nameof(supplierId));SupplierId=supplierId;SupplierInvoiceNumber=invoiceNumber?.Trim();} public void AddItem(PurchaseItem item){if(Status!=PurchaseStatus.Draft)throw new InvalidOperationException("Only draft purchases can be edited.");ArgumentNullException.ThrowIfNull(item);_items.Add(item);} public void MarkReceived(){if(Status!=PurchaseStatus.Draft)throw new InvalidOperationException("Only draft purchases can be received.");if(_items.Count==0)throw new InvalidOperationException("Purchase must contain items.");Status=PurchaseStatus.Received;} public void Cancel(){if(Status!=PurchaseStatus.Draft)throw new InvalidOperationException("Only draft purchases can be cancelled.");Status=PurchaseStatus.Cancelled;} }
